{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "A close analogue containing a 4-amidinophenyl group and carboxylate groups had absolute bioavailability too low for oral use in humans, directly supporting a low-F outcome for the query's amidine/carboxylate motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Avoralstat, which shares the 4-amidinophenyl amide and carboxylic acid pharmacophore, was reported to have low oral bioavailability in patients, reinforcing the low-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Folic acid, a structurally distant vitamin with a p-aminobenzoylglutamate motif, had absolute bioavailability 76.2 ± 13.8% in healthy subjects, providing weak contradictory evidence that is outweighed by the closer low-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a benzimidazole benzamidine bearing a free carboxylic acid and a pyridyl amide; such zwitterionic amidine/carboxylate motifs are associated with poor membrane permeability. The closest experimental analogues (C17, C36) both show low oral bioavailability in humans, while high-F evidence comes from structurally distant molecules such as folic acid with low transferability. Therefore low oral bioavailability (<20%) is the better-supported prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "Closest analogues have Morgan similarity below 0.3, limiting quantitative transfer.",
    "No human PK data for the exact benzimidazole-CH2-NH-benzamidine scaffold with the pyridyl-beta-alanine side chain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

